policy.rego:
package external_pilot

import rego.v1

default allow := false

# synthetic allow for probe > 0
allow if {
	input.request.body.probe > 0
}

# allow if supplier is not on hold
allow if {
	input.trusted.supplierOnHold == false
}

# allow if supplier is on hold but holdType is Payments
allow if {
	input.trusted.supplierOnHold == true
	input.trusted.holdType == "Payments"
}
